import os
QA=os.environ.get('GENO_QA','/tmp/geno-qa'); os.makedirs(QA,exist_ok=True); os.makedirs(QA+'/pp',exist_ok=True)
import asyncio, sys, subprocess, time
from playwright.async_api import async_playwright
ROOT=sys.argv[1]; PORT=8771
srv=subprocess.Popen([sys.executable,'-I','-m','http.server',str(PORT),'--directory',ROOT],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL); time.sleep(1)
URL=f'http://localhost:{PORT}/'
res=[]
def ok(name,cond,extra=''): res.append(bool(cond)); print(('PASS ' if cond else 'FAIL ')+name+(' — '+str(extra)[:300] if extra and not cond else ''))
async def main():
    async with async_playwright() as pw:
        b=await pw.chromium.launch()
        ctx=await b.new_context(viewport={'width':390,'height':844},device_scale_factor=2,has_touch=True,service_workers='block')
        page=await ctx.new_page(); errs=[]
        page.on('console',lambda m: errs.append(m.text) if m.type=='error' else None)
        page.on('pageerror',lambda e: errs.append(str(e)))
        await page.goto(URL+'#/about'); await page.wait_for_selector('input[name="lang"]')
        await page.check('input[name="lang"][value="tl"]'); await page.wait_for_timeout(200)
        body=await page.inner_text('main'); ok('about in Tagalog after switch (no reload)','Mga setting' in body and 'Privacy' in body and 'Naka-off ang passcode lock.' in body, body[:300])
        ok('lang stored',await page.evaluate("localStorage.getItem('g:v1:lang')")=='"tl"')
        await page.goto(URL+'#/'); await page.wait_for_selector('.hero')
        body=await page.inner_text('main'); ok('home in Tagalog','Buksan ang halimbawang pamilya' in body and 'Paano ito gumagana' in body, body[:300])
        await page.click('button[data-act="sample"]'); await page.wait_for_selector('#canvas svg')
        body=await page.inner_text('main'); ok('Genogram step in Tagalog','I-save bilang PDF' in body and 'Ipakita ang pamagat at petsa' in body and 'tao sa chart' in body, body[:400])
        svg=await page.inner_text('#canvas'); ok('chart drawing stays English','Ramon' in svg and ('Father' in svg or 'Separated' in svg or 'Close' in svg or 'Key' in svg or 'KEY' in svg), svg[:200])
        cid=await page.evaluate("document.querySelector('.editor').getAttribute('data-chart')")
        await page.goto(URL+'#/chart/'+cid); await page.wait_for_selector('.idx')
        await page.click('#m-fa .member__head'); await page.wait_for_selector('#m-fa.is-open')
        body=await page.inner_text('main'); ok('Family step in Tagalog','Magdagdag ng kapamilya' in body and 'Relasyon sa index person' in body and 'Mga magulang, tiyo at tiya' in body and 'Pumanaw na' in body, body[:400])
        vals=await page.eval_on_selector_all('#m-fa select[data-k="rel"] option','els=>els.map(e=>[e.value,e.textContent])')
        d=dict(vals); ok('relationship select keeps English values, Tagalog labels', d.get('Father')=='Ama' and d.get('Paternal uncle')=='Tiyo sa ama' and d.get("Sibling's spouse / partner")=='Asawa / kapareha ng kapatid', vals[:6])
        ok('selected value still English',await page.input_value('#m-fa select[data-k="rel"]')=='Father')
        segs=await page.eval_on_selector_all('#m-fa button[data-set="status"]','els=>els.map(e=>[e.dataset.v,e.textContent])'); ok('status buttons keep English data-v',segs==[['Living','Buhay'],['Deceased','Pumanaw na']],segs)
        cpl=await page.eval_on_selector_all('select[data-k="parentsRel"] option','els=>els.map(e=>[e.value,e.textContent])'); ok('couple list keeps English values, Tagalog labels',['Separated','Hiwalay'] in cpl and ['Cohabitation','Nagsasama (live-in)'] in cpl,cpl[:8])
        await page.click('#m-fa button[data-set="status"][data-v="Deceased"]'); await page.wait_for_timeout(600)
        st=await page.evaluate("(function(id){var c=JSON.parse(localStorage.getItem('g:v1:charts'));return c.byId[id].family.filter(function(m){return m.id==='fa'})[0].status;})", cid)
        ok('stored status stays English',st=='Deceased',st)
        await page.click('#undo-btn'); await page.wait_for_timeout(100)
        await page.evaluate("window.scrollTo(0,0)"); await page.screenshot(path=QA+'/family-tl.png')
        await page.click('#m-fa button[data-act="rm"]'); await page.wait_for_timeout(100)
        ok('removed message in Tagalog',(await page.inner_text('#ed-status')).startswith('Inalis si Ramon'),await page.inner_text('#ed-status'))
        await page.click('#undo-btn')
        await page.goto(URL+'#/chart/'+cid+'/lines'); await page.wait_for_selector('.linkrow')
        body=await page.inner_text('main'); ok('Relationships step in Tagalog','Mga linya ng relasyon' in body and 'Mga uri ng linya' in body and 'May alitan' in body, body[:300])
        lv=await page.eval_on_selector_all('select[data-k="type"]','els=>els[0]?Array.from(els[0].options).map(o=>[o.value,o.textContent]):[]'); ok('line-type select keeps English values',['Conflictual','May alitan'] in lv and ['Abusive toward','Nang-aabuso sa →'] in lv,lv)
        ok('line selected value English',await page.eval_on_selector('select[data-k="type"]','e=>e.value')=='Conflictual')
        await page.goto(URL+'#/symbols'); await page.wait_for_selector('.lib')
        body=await page.inner_text('main'); ok('Symbols in Tagalog','Mga simbolo at linya' in body and 'Nakunan (miscarriage)' in body and 'Sino ang tao' in body, body[:300])
        await page.goto(URL+'#/guide'); await page.wait_for_selector('.row'); ok('guide page title translated',(await page.title()).startswith('Paano gamitin'),await page.title())
        body=await page.inner_text('main'); ok('Guide in Tagalog','Paano gamitin' in body and 'Magsimula sa index person' in body, body[:300])
        ok('guide link markup intact',await page.locator('.page__head a[href="#/symbols"]').inner_text()=='pahina ng mga simbolo')
        await page.goto(URL+'#/about'); await page.wait_for_selector('input[name="lang"]')
        body=await page.inner_text('main'); ok('About in Tagalog','Mga setting' in body and 'Pumili ng 4 hanggang 12 numero.' in body, body[:300])
        ok('page title translated',(await page.title()).startswith('Tungkol dito'),await page.title())
        # switch back to English: re-render without reload
        await page.check('input[name="lang"][value="en"]'); await page.wait_for_timeout(200)
        body=await page.inner_text('main'); ok('switch back to English','Passcode lock is off.' in body, body[:300])
        await page.goto(URL+'#/symbols'); await page.wait_for_selector('.lib'); ok('Symbols back in English','Who the person is' in await page.inner_text('main'))
        ok('no console errors',not errs,errs)
        await b.close()
    srv.terminate()
    print(f'{sum(res)} of {len(res)} passed')
asyncio.run(main())
